query CompeteTournamentSearch($after: String, $filter: CompeteTournamentSearchFilterInput!, $first: Int, $sortBy: CompeteTournamentSearchSortInput, $sport: Sport!) {
  __typename
  competeTournamentSearch(
    sport: $sport
    filter: $filter
    sortBy: $sortBy
    first: $first
    after: $after
  ) {
    __typename
    edges {
      __typename
      cursor
      node {
        __typename
        ... on RbTournamentSearchResult {
          __typename
          distanceMeters
          organizer {
            __typename
            id
            isFavorited
            name
            physicalAddress {
              __typename
              adminArea1
              city
              formattedAddress
              latitude
              longitude
            }
          }
          tournament {
            __typename
            config {
              __typename
              ... on RiftboundTournamentConfig {
                __typename
                format
                participantCapacity
                playerFormat
                tournamentType
              }
            }
            entryFee {
              __typename
              currency
              minorUnits
            }
            id
            name
            pricing
            registrantCounts {
              __typename
              count
              status
            }
            startsAt
          }
        }
      }
    }
    pageInfo {
      __typename
      endCursor
      hasNextPage
    }
  }
}

